  THEN RAISE EXCEPTION 'Incoming geometry validation failed'; END IF;
END $$;
CREATE TABLE IF NOT EXISTS timewalk."1776_philadelphia_building_parcels" (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  source_row bigint NOT NULL,
  original_id text,
  geom geometry(MultiPolygon,3857) NOT NULL CHECK (ST_IsValid(geom) AND NOT ST_IsEmpty(geom)),
  label_origin text NOT NULL DEFAULT 'manual',
  digitizer text NOT NULL DEFAULT 'Sunil Prabhu',
  source_map text NOT NULL DEFAULT 'tw_1776_philadelphia_map_easburn_plan_v2_cog',
  target_year integer NOT NULL DEFAULT 1776,
  source_repo text NOT NULL DEFAULT 'https://k7oth9.gitea.cloud/TimeWalk/NYC_Maps',
  source_commit text NOT NULL DEFAULT '29539f1',
  dataset_sha256 text NOT NULL DEFAULT 'cb06cf16d9f7d37edd8ce9f901588bd80da57845869f75db4d41302d7f5c8c2b',
  imported_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (dataset_sha256, source_row)
);
-- A populated pre-existing table is allowed only if it is an exact replay.
-- Never overwrite reviewed rows or silently append to another dataset.
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM timewalk."1776_philadelphia_building_parcels") AND (
    (SELECT count(*) FROM timewalk."1776_philadelphia_building_parcels") <> 51 OR EXISTS (
      SELECT 1 FROM incoming_sunil_parcels s FULL JOIN timewalk."1776_philadelphia_building_parcels" t ON s.source_row=t.source_row
      WHERE s.source_row IS NULL OR t.source_row IS NULL
        OR t.dataset_sha256 IS DISTINCT FROM 'cb06cf16d9f7d37edd8ce9f901588bd80da57845869f75db4d41302d7f5c8c2b'
        OR t.original_id IS DISTINCT FROM s.original_id OR NOT ST_Equals(t.geom,s.geom)
        OR t.label_origin IS DISTINCT FROM 'manual'
        OR t.source_map IS DISTINCT FROM 'tw_1776_philadelphia_map_easburn_plan_v2_cog'
    )
  ) THEN RAISE EXCEPTION 'Existing table differs; refusing to overwrite or append'; END IF;
END $$;
INSERT INTO timewalk."1776_philadelphia_building_parcels" (source_row,original_id,geom)
SELECT source_row,original_id,geom FROM incoming_sunil_parcels
ON CONFLICT (dataset_sha256,source_row) DO NOTHING;
CREATE INDEX IF NOT EXISTS sunil_1776_philadelphia_building_parcels_geom_idx ON timewalk."1776_philadelphia_building_parcels" USING gist (geom);
ALTER TABLE timewalk."1776_philadelphia_building_parcels" ENABLE ROW LEVEL SECURITY;
COMMENT ON TABLE timewalk."1776_philadelphia_building_parcels" IS 'Sunil manual parcels; 51 records from NYC_Maps 29539f1. Selected training-label source, replacing Geo-SAM. Not an independently verified benchmark or exhaustive tile annotation.';
DO $$ BEGIN
  IF (SELECT count(*) FROM timewalk."1776_philadelphia_building_parcels") <> 51 THEN RAISE EXCEPTION 'Import count mismatch'; END IF;
END $$;
COMMIT;
SELECT count(*) AS parcels, count(*) FILTER (WHERE ST_IsValid(geom)) AS valid,
       array_agg(DISTINCT ST_SRID(geom)) AS srids FROM timewalk."1776_philadelphia_building_parcels";
